function M.now()
return os.clock()
end
function M.json(gb)
local hb,ib=pcall(F.JSONEncode,F,gb)
return hb and ib or Atc[1437]
end
function M.unjson(jb)
local kb,mb=pcall(F.JSONDecode,F,jb)
return kb and mb or nil
end
function M.readJson(nb)
local ob,pb=pcall(function()
return isfile(nb)and readfile(nb)or nil
end)
return ob and pb and M.unjson(pb)or nil
end
function M.writeJson(qb,rb)
pcall(function()
if not isfolder(H.FOLDER)then
makefolder(H.FOLDER)
end
end)
pcall(writefile,qb,M.json(rb))
end
function M.fmt(sb)
sb=tonumber(sb)or 0
if sb>=1e6 then
return string.format(Atc[1438],sb/1e6)
end
if sb>=1e4 then
return string.format(Atc[1439],sb/1e3)
end
return tostring(math.floor(sb+0.5))
end
function M.clamp(tb,ub,vb)
return math.max(ub,math.min(vb,tb))
end
function M.count(wb)
local xb=0
for yb in pairs(wb or{})do
xb=xb+1
end
return xb
end
function M.list(zb)
if type(zb)~=Atc[1440]then
return{}
end
if#zb>0 then
return zb
end
local Ab={}
for Bb in pairs(zb)do
table.insert(Ab,Bb)
