function eb.skinSet(Sm)
local Tm=type(Sm)==Atc[1440]and Sm.id
return(Tm==eb.ID or Tm==Atc[1679]or(type(Sm)==Atc[1440]and Sm.portal_group==Atc[1677]))and eb.SKIN_SET or nil
end
function eb.skinFits(Um,Vm)
