return Vm.for_unit==Um or Vm.for_unit==Xm or(Vm.for_units~=nil and(Vm.for_units[Um]or Vm.for_units[Xm])and true)or false
end
function eb.team()
local Ym=J.simTeam and J.simTeam[Atc[1627]..tostring(eb.ID)]
local Zm=H.session()
local _m={}
