function eb.skinPlan()
local dn,en=H.session(),H.prof()
local fn=H.data(Atc[1576])or{}
local gn=(en.inventory and en.inventory.unique_items)or en.unique_items or{}
local hn,jn={},{kinds={},sell={},wear={},pearls=0,missing={}}
for kn,ln in pairs(gn)do
local mn=type(ln)==Atc[1440]and H.Items[ln.item_id]
if mn and mn.item_group==Atc[1576]and mn._skin_set==eb.SKIN_SET and mn.usage and fn[mn.usage.skin_id]then
local nn=hn[ln.item_id]
if not nn then
nn={id=ln.item_id,name=mn.name,rarity=mn.rarity,skinId=mn.usage.skin_id,skin=fn[mn.usage.skin_id],uuids={}}
hn[ln.item_id]=nn
table.insert(jn.kinds,nn)
end
table.insert(nn.uuids,ln.uuid or kn)
end
end
table.sort(jn.kinds,function(pn,qn)
return pn.name<qn.name
end)
local rn=eb.team()
local sn=dn.profile_data.collection.owned_units
for tn,un in ipairs(jn.kinds)do
for vn,wn in pairs(sn)do
if eb.skinFits(wn.unit_id,un.skin)then
un.fits=true
break
end
end
local xn=un.rarity==Atc[1680]or un.rarity==Atc[1681]
un.keep=(un.fits or xn)and 1 or 0
for yn=un.keep+1,#un.uuids do
table.insert(jn.sell,{uuid=un.uuids[yn],name=un.name,pearls=eb.SKIN_PRICE[un.rarity]or 0})
jn.pearls=jn.pearls+(eb.SKIN_PRICE[un.rarity]or 0)
end
end
for zn,An in ipairs(rn)do
local Bn=An.skin and An.skin._skin_id and fn[An.skin._skin_id]
if not(Bn and Bn._skin_set==eb.SKIN_SET)then
for Cn,Dn in pairs(fn)do
if type(Dn)==Atc[1440]and Dn._skin_set==eb.SKIN_SET and eb.skinFits(An.unit_id,Dn)then
local En=Cn..Atc[1682]
if hn[En]then
table.insert(jn.wear,{uuid=hn[En].uuids[1],unit=An.uuid,unitName=N.name(An.unit_id),name=hn[En].name})
else
table.insert(jn.missing,{item=En,unitName=N.name(An.unit_id),name=Dn.name,boost=tonumber(Dn._damage_boost)or 0,drop=eb.SKIN_DROP[Dn._skin_rarity]or 0})
end
end
end
end
end
return jn
end
function eb.starPlan(Fn)
Fn=Fn or eb.skinPlan()
local Gn=H.Items[eb.STAR]or{}
local Hn=tonumber(Gn._mythic_unit_pity)or 400
local In=(H.prof().capsule_pity_data or{})[eb.STAR]or{}
local Jn=tonumber(In.opens_since_mythic_unit)or 0
local Kn={opened=tonumber(In.total_opens)or 0,left=math.max(1,Hn-Jn),units={}}
local Ln=tonumber(H.cur(Atc[1676]))or 0
Kn.can=math.max(0,math.floor((Ln-(tonumber(I.pearlFloor)or 0))/eb.STAR_COST))
local Mn={}
for Nn,On in pairs(H.session().profile_data.collection.owned_units)do
Mn[On.unit_id]=true
local Pn=H.Units[On.unit_id]
if Pn and Pn.evolved and Pn.evolved.from then
Mn[Pn.evolved.from]=true
end
end
for Qn,Rn in pairs(Gn.usage and Gn.usage.possible_rewards or{})do
local Sn=Rn.unit or Rn.item
if Sn and H.Units[Sn]and H.Units[Sn].rarity==Atc[1681]and not Mn[Sn]then
table.insert(Kn.units,N.name(Sn))
end
end
table.sort(Kn.units)
local Tn={}
if#Fn.missing>0 then
local Un=Fn.missing[1]
table.insert(Tn,string.format(Atc[1683],Un.name,Un.unitName))
end
if#Kn.units>0 then
table.insert(Tn,string.format(Atc[1684],table.concat(Kn.units,Atc[1536])))
end
Kn.why=table.concat(Tn,Atc[1685])
Kn.open= #Tn>0 and math.min(Kn.can,#Kn.units>0 and Kn.left or 100)or 0
return Kn
end
function eb.skinText()
local Vn,Wn=pcall(eb.skinPlan)
if not Vn then
return Atc[1686]..tostring(Wn)
end
local Xn={}
local Yn={}
for Zn,ao in ipairs(Wn.kinds)do
table.insert(Yn,string.format(Atc[1687],ao.name,#ao.uuids>1 and(Atc[1688].. #ao.uuids)or Atc[369],(tonumber(ao.skin._damage_boost)or 0)*100,ao.fits and Atc[369]or Atc[1689]))
end
table.insert(Xn,Atc[1690]..(#Yn>0 and table.concat(Yn,Atc[1536])or Atc[1691])..Atc[1692])
if#Wn.wear>0 then
local bo={}
for co,eo in ipairs(Wn.wear)do
table.insert(bo,eo.name..Atc[1693]..eo.unitName)
end
table.insert(Xn,Atc[1694]..table.concat(bo,Atc[1536])..Atc[1692])
end
for fo,go in ipairs(Wn.missing)do
table.insert(Xn,string.format(Atc[1695],go.name,go.unitName,go.boost*100,go.drop*100))
end
if#Wn.sell>0 then
local ho={}
for io,jo in ipairs(Wn.sell)do
ho[jo.name]=(ho[jo.name]or 0)+1
end
local ko={}
for mo,no in pairs(ho)do
table.insert(ko,no..Atc[1696]..mo)
end
table.sort(ko)
table.insert(Xn,string.format(Atc[1697],table.concat(ko,Atc[1536]),M.fmt(Wn.pearls)))
else
table.insert(Xn,Atc[1698])
end
local oo,po=pcall(eb.starPlan,Wn)
if oo then
table.insert(Xn,string.format(Atc[1699],po.opened,po.left,M.fmt(po.left*eb.STAR_COST)))
if po.open>0 then
table.insert(Xn,string.format(Atc[1700],po.open,M.fmt(po.open*eb.STAR_COST),po.why,M.fmt(I.pearlFloor)))
elseif po.why~=Atc[369]then
table.insert(Xn,string.format(Atc[1701],po.why,M.fmt(I.pearlFloor)))
else
table.insert(Xn,Atc[1702])
end
end
if P.pickNote.skins then
table.insert(Xn,P.pickNote.skins)
end
return table.concat(Xn,Atc[1451])
end
function eb.skinTick()
if not(I.skinSmart or I.starOpen)or not(J.live.event and eb.is(J.live.event.level))then
return
end
if(j.req.back.skins or 0)>M.now()then
return
end
local qo=H.session()
local function ro(so,uo,vo)
local wo=j.gameSaid(uo)
P.pickNote.skins=string.format(Atc[1703],so,tostring(wo or vo or Atc[1704]))
j.log(1,Atc[1637],P.pickNote.skins)
j.backoff(Atc[1705],1800)
end
local xo=eb.skinPlan()
if I.skinSmart then
local yo=xo.wear[1]
if yo and(j.req.back.skinWear or 0)<=M.now()then
local zo=db.slotOf(yo.unit)
if zo then
J.str.reequip={uuid=yo.unit,slot=zo}
j.saveNow()
j.request(Atc[1706],Atc[1707],yo.unit)
local Ao=M.now()
while M.now()-Ao<4 and db.slotOf(yo.unit)do
task.wait(0.25)
end
end
local Bo=M.now()
local Co,Do=j.request(Atc[1708],Atc[1709],yo.uuid,{unit_uuid=yo.unit})
local function Eo()
local Fo=qo.collection:get_unit_by_uuid(yo.unit)
return Fo and Fo.skin~=nil
end
while M.now()-Bo<5 and not Eo()do
task.wait(0.25)
end
if zo then
db.reequip()
end
if Eo()then
j.log(1,Atc[1637],string.format(Atc[1710],yo.name,yo.unitName))
P.pickNote.skins=nil
xo=eb.skinPlan()
else
local Go=j.gameSaid(Bo)
P.pickNote.skins=string.format(Atc[1711],yo.name,tostring(Go or Do or Atc[1704]))
j.log(1,Atc[1637],P.pickNote.skins)
j.backoff(Atc[1708],1800)
end
end
if#xo.sell>0 then
local Ho,Io={},0
for Jo=1,math.min(50,#xo.sell)do
table.insert(Ho,xo.sell[Jo].uuid)
Io=Io+xo.sell[Jo].pearls
end
local Ko=tonumber(H.cur(Atc[1676]))or 0
local Lo=M.now()
local Mo,No=j.request(Atc[1712],Atc[1713],Ho)
while M.now()-Lo<5 and(tonumber(H.cur(Atc[1676]))or 0)<=Ko do
task.wait(0.25)
end
local Oo=(tonumber(H.cur(Atc[1676]))or 0)-Ko
if Oo<=0 then
return ro(Atc[1714],Lo,No)
end
R.add(string.format(Atc[1715],#Ho),#Ho,Atc[1705],string.format(Atc[1716],M.fmt(Oo)))
P.pickNote.skins=nil
end
end
if I.starOpen then
local Po=qo.inventory
local function Qo()
local Ro,So=pcall(Po.get_number_of_owned_item,Po,eb.STAR)
return Ro and tonumber(So)or 0
end
local To=M.now()
for Uo=1,8 do
if M.now()-To>15 or not j.alive or j.where~=Atc[1507]then
break
end
local Vo=Qo()
local Wo=eb.starPlan(eb.skinPlan())
local Xo=M.now()
if Vo>0 then
local Yo,Zo=j.request(Atc[1717],Atc[1718],eb.STAR,{use10=Vo>=10,use_all=false})
while M.now()-Xo<6 and Qo()>=Vo do
task.wait(0.25)
end
if Qo()>=Vo then
return ro(Atc[1719],Xo,Zo)
end
j.log(1,Atc[1637],string.format(Atc[1720],Vo-Qo(),(tonumber(((H.prof().capsule_pity_data or{})[eb.STAR]or{}).total_opens)or 0)))
P.pickNote.skins=nil
elseif Wo.open>0 then
local _o=Wo.open>=10 and 10 or 1
local ap=tonumber(H.cur(Atc[1676]))or 0
local bp,cp=j.request(Atc[1721],Atc[1722],eb.STAR,Atc[1457],Atc[1723],tostring(_o))
while M.now()-Xo<5 and Qo()<=0 do
task.wait(0.25)
end
if Qo()<=0 then
return ro(Atc[1724],Xo,cp)
end
R.add(string.format(Atc[1725],Qo()),ap-(tonumber(H.cur(Atc[1676]))or 0),Atc[1726],Atc[1727]..Wo.why)
P.pickNote.skins=nil
else
break
end
end
end
end
