table.insert(cx,ux)
end
end
end
for vx,wx in ipairs(cx)do
if wx.kind==Atc[1594]then
local xx=cx[1]
if vx>1 and xx.kind~=Atc[1592]and not(xx.kind==Atc[1460]and xx.started)then
table.remove(cx,vx)
table.insert(cx,1,wx)
wx.why=Atc[1910]..(wx.why or Atc[369])
end
