end
end
for yx,zx in ipairs(cx)do
if zx.kind==Atc[1593]then
local Ax=cx[1]
if yx>1 and(zx.p or 0)>=0.25 and Ax.kind~=Atc[1592]and Ax.kind~=Atc[1594]and not(Ax.kind==Atc[1460]and Ax.started)and not tostring(Ax.why):find(Atc[1911],1,true)then
