function db.relicWorth(RI,SI)
local TI=SI._unique_item_data and SI._unique_item_data._unique_relic_data
if not TI then
return 0
end
local VI=H.Items[SI.item_id]or{}
local WI,XI=N.types(RI.unit_id)
if VI.main_damage_type and VI.main_damage_type~=Atc[2042]and VI.main_damage_type~=XI then
return 0
end
local YI,ZI=0,0
for _I,aJ in pairs(TI._core_damage_type_buffs or{})do
if WI[aJ.damage_type]then
YI=YI+(tonumber(aJ.mul)or 0)+(tonumber(aJ.add_upg)or 0)*0.01+(tonumber(aJ.pen)or 0)*0.001
ZI=ZI+(tonumber(aJ.crit)or 0)
end
end
YI=YI+ZI*0.5
local bJ=N.rows(RI.unit_id)
local cJ=bJ and bJ[bJ.max]
local dJ=(cJ and tonumber(cJ.cd)or 0)*N.mult(RI,Atc[1575])
for eJ,fJ in pairs(TI._unique_relic_effects or{})do
local gJ=type(fJ.params)==Atc[1440]and fJ.params or{}
if fJ.id==Atc[2043]then
local hJ=math.min(1,(tonumber(gJ.extra_damage)or 0)*dJ/math.max(1,tonumber(gJ.time_interval)or 40))
local iJ=N.DRONES and N.DRONES[RI.unit_id]
if iJ and iJ.late and dJ>0 then
local jJ=1/dJ
hJ=hJ*jJ/(jJ+(tonumber(iJ.max)or 0)*(tonumber(iJ.late.dmg)or 0)*(tonumber(iJ.hits)or 1)/math.max(0.1,tonumber(iJ.late.cd)or 4))
end
YI=YI+hJ
elseif fJ.id==Atc[2044]then
YI=YI+(tonumber(gJ.dmg_buff)or 0)*0.25
elseif fJ.id==Atc[2045]then
YI=YI+(tonumber(gJ.dmg_buff)or 0)*ZI
elseif fJ.id==Atc[2046]then
if WI.magic then
YI=0
else
YI=YI+(tonumber(gJ.dmg_buff)or 0)*0.3
end
elseif fJ.id==Atc[2047]then
if WI.water_damage then
YI=YI+0.05
end
end
end
return YI
end
function db.relicPlan()
local kJ=H.session()
if not kJ then
return nil
end
local lJ=kJ.inventory and kJ.inventory.inventory_profile_data or{}
local mJ={}
for nJ,oJ in ipairs(lJ.unique_items or{})do
if type(oJ)==Atc[1440]and oJ.uuid and(H.Items[oJ.item_id]or{}).item_group==Atc[2048]then
table.insert(mJ,oJ)
end
end
local pJ={}
for qJ,rJ in ipairs(N.equipped())do
local sJ=rJ.data and rJ.data.rarity
if not N.isFarm(rJ.id)and(sJ==Atc[1680]or sJ==Atc[1681]or sJ==Atc[2027]or sJ==Atc[2049])then
local tJ=db.share(rJ.id)
if not J.str.share[rJ.id]then
tJ=math.min(tJ,0.15)
end
local uJ={}
for vJ,wJ in ipairs(mJ)do
local xJ=db.relicWorth(rJ.u,wJ)*tJ*100
if xJ>0.01 then
table.insert(uJ,{it=wJ,w=xJ})
end
end
table.sort(uJ,function(yJ,zJ)
if yJ.w~=zJ.w then
return yJ.w>zJ.w
end
return yJ.it.uuid<zJ.it.uuid
end)
local AJ,BJ={},{}
for CJ,DJ in ipairs(uJ)do
local EJ=BJ[DJ.it.item_id]or 0
if#AJ<6 and EJ<((H.Items[DJ.it.item_id]or{}).unique_equip and 1 or 2)then
BJ[DJ.it.item_id]=EJ+1
table.insert(AJ,DJ)
end
end
if rJ.u._equipped_relic then
local FJ=false
for GJ,HJ in ipairs(AJ)do
if HJ.it.uuid==rJ.u._equipped_relic then
FJ=true
end
end
local IJ=not FJ and kJ.inventory:get_item_by_uuid(rJ.u._equipped_relic)
if IJ then
table.insert(AJ,{it=IJ,w=db.relicWorth(rJ.u,IJ)*tJ*100})
end
end
table.insert(pJ,{e=rJ,share=tJ,opts=AJ})
end
end
local JJ,KJ={},-1
local LJ,MJ,NJ={},{},{}
local function OJ(PJ,QJ)
if PJ> #pJ then
if QJ>KJ then
KJ=QJ
JJ=table.clone(LJ)
end
return
end
local RJ=pJ[PJ]
LJ[RJ.e.uuid]=nil
OJ(PJ+1,QJ)
for SJ,TJ in ipairs(RJ.opts)do
local UJ=(H.Items[TJ.it.item_id]or{}).unique_equip
if not MJ[TJ.it.uuid]and not(UJ and NJ[TJ.it.item_id])then
MJ[TJ.it.uuid]=true
if UJ then
NJ[TJ.it.item_id]=true
end
LJ[RJ.e.uuid]=TJ.it.uuid
OJ(PJ+1,QJ+TJ.w+(TJ.it.uuid==RJ.e.u._equipped_relic and 0.01 or 0))
LJ[RJ.e.uuid]=nil
MJ[TJ.it.uuid]=nil
if UJ then
NJ[TJ.it.item_id]=nil
end
end
end
end
OJ(1,0)
local VJ,WJ=0,{}
for XJ,YJ in ipairs(pJ)do
local ZJ=YJ.e.u._equipped_relic and kJ.inventory:get_item_by_uuid(YJ.e.u._equipped_relic)
local _J=ZJ and db.relicWorth(YJ.e.u,ZJ)*YJ.share*100 or 0
VJ=VJ+_J
local aK=JJ[YJ.e.uuid]and kJ.inventory:get_item_by_uuid(JJ[YJ.e.uuid])
local bK=aK and db.relicWorth(YJ.e.u,aK)*YJ.share*100 or 0
table.insert(WJ,string.format(Atc[2050],N.name(YJ.e.id),ZJ and(H.Items[ZJ.item_id]or{}).name or Atc[1691],_J,aK and(H.Items[aK.item_id]or{}).name or Atc[1691],bK))
end
return JJ,KJ-VJ,WJ,pJ
end
