function db.xpGuess(VL)
local WL=VL.level and H.Levels[VL.level]
if not WL then
return 0
end
local XL=math.min(9,tonumber(WL.story_world_rank)or tonumber(VL.rank)or 9)
local YL=tonumber(WL.story_level_rank)or 6
local ZL=(VL.kind==Atc[1476]and 1.5 or 1)*(XL>5 and 2 or 1)
local _L=2.1564^(XL-1)*(40+10*YL)/ZL
if VL.kind==Atc[1459]then
_L=3*30*2.1564^(XL-1)/ZL
end
local aM=XL>=9 and 0.3 or(XL>=7 and 0.5 or 1)
return _L*aM*6
end
function db.modeBonus(bM)
