UO[aP]=true
end
for bP,cP in ipairs(J.goals or{})do
UO[cP.uuid]=true
for dP,eP in ipairs(cP.eats or{})do
VO[eP.id]=true
end
end
for fP,gP in ipairs(J.str and J.str.core or{})do
UO[gP]=true
end
local hP=ab.strongest(10)
local iP,jP={},0
for kP,lP in pairs(TO.profile_data.collection.owned_units)do
local mP=TO.collection:get_unit_by_uuid(kP)or lP
local nP,oP,pP=pcall(H.USC.is_unit_good_for_fusion,RO,mP)
if nP and oP and not(lP._locked or mP._locked)and not UO[kP]and not VO[mP.unit_id]and not(lP._equipped_relic or mP._equipped_relic)and not(lP.shiny or mP.shiny)and not N.trait(mP)and not(lP.further_modifiers and lP.further_modifiers.limit_break)then
local qP=ab.fodderOrder(mP.unit_id)
if qP and not hP[kP]then
local rP,sP=pcall(N.score,mP)
table.insert(iP,{uuid=kP,id=mP.unit_id,pts=tonumber(pP)or 1,sc=rP and sP or 0,order=qP})
jP=jP+(tonumber(pP)or 1)
end
end
end
table.sort(iP,function(tP,uP)
if tP.order~=uP.order then
return tP.order<uP.order
end
if tP.sc~=uP.sc then
return tP.sc<uP.sc
end
return tP.uuid<uP.uuid
