for eeb,feb in ipairs(beb or{})do
local geb=tostring(feb.lane)
if feb.lane~=nil and not ceb[geb]then
ceb[geb]=true
table.insert(deb,geb)
end
end
table.sort(deb)
return#deb>=2 and deb or nil
end
function W.spotMask(heb,ieb,jeb)
