function W.evaluate(Qmb,Rmb)
local Smb=W.run(Qmb,Rmb,{hpMul=1})
local Tmb={won=Smb.won,wave=Smb.wave,minutes=Smb.t/60,aliveAt=Smb.aliveAt,total=Qmb.total,at=os.time()}
if Qmb.infinite and W.unbound(Qmb.ld)then
Tmb.p=1
Tmb.margin=Smb.won and string.format(Atc[2642],Qmb.total)or string.format(Atc[2643],Smb.wave,Smb.t/60)
elseif Smb.won then
local Umb=W.run(Qmb,Rmb,{hpMul=1.3})
Tmb.p=Umb.won and 0.92 or 0.7
Tmb.margin=Umb.won and Atc[2644]or Atc[2645]
else
local Vmb=W.run(Qmb,Rmb,{hpMul=0.75})
Tmb.p=Vmb.won and 0.25 or 0.05
Tmb.margin=Vmb.won and string.format(Atc[2646],Smb.wave)or string.format(Atc[2647],Smb.wave,Qmb.total)
if not Vmb.won then
local Wmb=W.run(Qmb,Rmb,{hpMul=0.25})
if not Wmb.won then
Tmb.p,Tmb.hopeless=0.005,true
Tmb.margin=string.format(Atc[2648],Smb.wave,Qmb.total)
end
end
end
return Tmb
end
function W.trust(Xmb,Ymb)
local Zmb=Xmb.cal or{}
if type(Zmb.alive)~=Atc[1440]or Zmb.teamSig~=W.sig((function()
local _mb={}
for anb,bnb in ipairs(Ymb)do
table.insert(_mb,bnb.u)
end
return _mb
end)())then
return nil
end
if Xmb.key==Atc[1734]and not Zmb.aliveLvl then
return nil
end
if Zmb.aliveLvl and Xmb.ld and Xmb.ld.id and Zmb.aliveLvl~=tostring(Xmb.ld.id)..(eb.is(Xmb.ld.id)and(Atc[2649]..tostring(Xmb.ld.map))or Atc[369])then
return nil
end
local cnb=W.run(Xmb,Ymb,{hpMul=1})
local dnb,enb,fnb=0,0,0
for gnb=3,math.min(cnb.wave,tonumber(Zmb.lastWave)or 99)do
local hnb=tonumber(Zmb.alive[tostring(gnb)])
local inb=cnb.aliveAt[gnb]
if hnb and inb and hnb>0 then
dnb=dnb+hnb
enb=enb+inb
fnb=fnb+1
end
end
if fnb<2 or enb<=0 then
return nil
end
local jnb=dnb/enb
return{ratio=jnb,ok=jnb>=0.75 and jnb<=1.33,waves=fnb}
end
W.GROWN_LEVEL,W.GROWN_MIN=50,6
function W.grownKinds()
local knb=H.session()
local lnb,mnb={},0
for nnb,onb in pairs(knb.profile_data.collection.owned_units)do
local pnb=onb.unit_id
if not lnb[pnb]and H.Units[pnb]and not N.isFarm(pnb)and N.rows(pnb)and not N.hidden(pnb)then
local qnb,rnb=pcall(H.USC.calculate_level,pnb,tonumber(onb.xp)or 0)
if qnb and(tonumber(rnb)or 0)>=W.GROWN_LEVEL then
lnb[pnb]=true
mnb=mnb+1
end
end
end
return mnb
end
function W.pool(snb,tnb)
local unb=H.session()
local vnb,wnb={},{}
local xnb=W.grownKinds()>=W.GROWN_MIN
for ynb,znb in pairs(unb.profile_data.collection.owned_units)do
local Anb=unb.collection:get_unit_by_uuid(znb.uuid)or znb
local Bnb,Cnb=pcall(H.USC.calculate_level,Anb.unit_id,tonumber(Anb.xp)or 0)
local Dnb=N.isFarm(Anb.unit_id)or not xnb or(Bnb and(tonumber(Cnb)or 0)>=W.GROWN_LEVEL)
if H.Units[Anb.unit_id]and N.rows(Anb.unit_id)and not N.hidden(Anb.unit_id)and Dnb then
local Enb=N.isFarm(Anb.unit_id)
local Fnb,Gnb=pcall(Enb and function()
return N.farm(Anb,N.rows(Anb.unit_id).max)
end or N.score,Anb,snb)
Gnb=(Fnb and Gnb or 0)*(Enb and 1 or N.skinMul(Anb,tnb and tnb.skinSet))
local Hnb=Enb and wnb or vnb
if not Hnb[Anb.unit_id]or Gnb>Hnb[Anb.unit_id].sc then
Hnb[Anb.unit_id]={u=Anb,sc=Gnb}
end
end
end
local Inb,Jnb={},{}
for Knb,Lnb in pairs(vnb)do
table.insert(Inb,Lnb)
end
for Mnb,Nnb in pairs(wnb)do
table.insert(Jnb,Nnb)
end
table.sort(Inb,function(Onb,Pnb)
return Onb.sc>Pnb.sc
end)
table.sort(Jnb,function(Qnb,Rnb)
return Qnb.sc>Rnb.sc
end)
local Snb={}
for Tnb=1,math.min(10,#Inb)do
table.insert(Snb,Inb[Tnb].u)
end
local Unb,Vnb={},{}
for Wnb=11,#Inb do
local Xnb=N.rows(Inb[Wnb].u.unit_id)
for Ynb=0,Xnb.max do
if Xnb[Ynb]and Xnb[Ynb].atk and N.attackInfo(Xnb[Ynb].atk,Xnb[Ynb].range).dot>0 then
table.insert(Ynb==0 and Unb or Vnb,Inb[Wnb].u)
break
end
end
end
for Znb=1,math.min(4,#Unb)do
table.insert(Snb,Unb[Znb])
end
for _nb=1,math.min(2,#Vnb)do
table.insert(Snb,Vnb[_nb])
end
for aob=1,math.min(3,#Jnb)do
table.insert(Snb,Jnb[aob].u)
end
local bob={}
for cob=11,#Inb do
local dob=N.rows(Inb[cob].u.unit_id)[0]
local eob=dob and dob.atk and N.attackInfo(dob.atk,dob.range)
if eob and(eob.slowTime>0 or eob.stun>0)then
table.insert(bob,Inb[cob].u)
end
end
for fob=1,math.min(3,#bob)do
table.insert(Snb,bob[fob])
end
if tnb and((tnb.flyChance or 0)>0 or tnb.mapFly or(tnb.shield or 0)>0)then
local gob,hob={},{}
for iob=11,#Inb do
local job=Inb[iob].u
local kob=N.rows(job.unit_id)[0]
if N.airFrom(job.unit_id)==0 then
table.insert(gob,job)
end
local lob,mob=tonumber(kob and kob.cd)or 0,tonumber((H.Units[job.unit_id]or{}).cost)or 0
if lob>0 and mob>0 and N.range(job,0)>=15 then
local nob=N.attackInfo(kob.atk,kob.range)
table.insert(hob,{u=job,v=nob.n*nob.hits/lob/mob*math.min(6,N.cap(job))})
end
end
table.sort(hob,function(oob,pob)
return oob.v>pob.v
end)
for qob=1,math.min(4,#gob)do
table.insert(Snb,gob[qob])
end
for rob=1,math.min(6,#hob)do
table.insert(Snb,hob[rob].u)
end
end
local sob,tob={},{}
for uob,vob in ipairs(Snb)do
if not sob[vob]then
sob[vob]=true
table.insert(tob,vob)
end
end
tob.rest={}
for wob,xob in ipairs(Inb)do
if not sob[xob.u]then
table.insert(tob.rest,xob.u)
end
end
return tob
end
function W.objective(yob)
return(yob.won and 1000 or 0)+yob.wave*10-(yob.won and yob.t/60 or((yob.left or 1)*9-math.min(9,yob.t/60)))
end
W.LADDER={1,1.3,1.7,2.2,3,4,6,8,12,16,24}
function W.cliff(zob,Aob,Bob)
local Cob
for Dob,Eob in ipairs(W.LADDER)do
Cob=W.run(zob,Aob,{hpMul=Eob,layout=Bob})
if not Cob.won then
return Eob,Cob
end
end
return W.LADDER[#W.LADDER],Cob
end
function W.exam(Fob,Gob)
local Hob,Iob,Job=W.teamFrom(Gob,Fob.map),0,0
for Kob,Lob in ipairs(W.LADDER)do
local Mob,Nob=0,0
for Oob,Pob in ipairs({0.92,1,1.08})do
local Qob=W.run(Fob,Hob,{hpMul=Lob*Pob})
if Qob.won then
Mob=Mob+1
end
Nob=Nob+Qob.wave
end
Iob,Job=Iob+Mob,Nob/3
task.wait()
if Mob==0 then
break
end
end
return Iob,Job
end
W.ZONE_CLOSE,W.ZONE_GAIN=1.3,20
function W.zoneKey(Rob)
return tostring(Rob.key)..Atc[1551]..tostring(Rob.map)
end
function W.zoneChoice(Sob,Tob,Uob,Vob)
if I.killZone==false or Sob.zone or(Sob.infinite and W.unbound(Sob.ld))then
return false
end
local Wob=J.zoneRec[W.zoneKey(Sob)]
local Xob=Wob and(Wob.style==Atc[2631]or(Wob.style==nil and Wob.zone==true))
if Wob and Wob.won then
return Xob==true,Xob and Atc[2650]or nil
end
if Wob and Xob then
return false,Atc[2651]
end
local Yob=J.modes[Sob.key]
local Zob=Yob and tonumber(Yob.streak)or 0
if not Wob and Yob and(tonumber(Yob.wins)or 0)>0 and Zob==0 and Sob.key~=Atc[1734]and Sob.key~=Atc[1730]then
return false
end
local _ob=Wob~=nil or Zob>0
local apb=Vob and Uob<=1 or(not Vob and Uob<=W.ZONE_CLOSE)
if not(_ob or apb)then
return false
end
local bpb=table.clone(Sob)
bpb.zone=true
local function cpb(dpb)
local epb=0
for fpb,gpb in ipairs({0.92,1,1.08})do
epb=epb+W.objective(W.run(dpb,Tob,{hpMul=Uob*gpb}))
end
return epb/3
end
local hpb=cpb(bpb)-cpb(Sob)
if _ob and hpb> -W.ZONE_GAIN then
return true,Atc[2652],hpb
end
if apb and hpb>W.ZONE_GAIN then
return true,string.format(Atc[2653],Uob),hpb
end
return false,nil,hpb
end
function W.strength(ipb,jpb)
local kpb,lpb,mpb,npb,opb=W.teamFrom(jpb,ipb.map),0,0,0,0
for ppb,qpb in ipairs(W.LADDER)do
local rpb,spb=0,0
for tpb,upb in ipairs({0.92,1,1.08})do
local vpb=W.run(ipb,kpb,{hpMul=qpb*upb})
if vpb.won then
rpb=rpb+1
end
spb=spb+vpb.wave
end
lpb,opb=lpb+rpb,spb/3
if qpb==1 then
mpb,npb=rpb,spb/3
end
task.wait()
if rpb==0 then
break
end
end
return lpb,mpb,npb,opb
end
function W.bestTeam(wpb,xpb,ypb,zpb)
local Apb=M.now()
zpb=zpb or 25
local Bpb=table.clone(xpb)
local Cpb,Dpb=W.cliff(wpb,W.teamFrom(Bpb,wpb.map))
local function Epb(Fpb)
local Gpb=0
for Hpb,Ipb in ipairs(Fpb)do
if N.isFarm(Ipb.unit_id)then
Gpb=Gpb+1
end
end
return Gpb
end
local Jpb=Epb(ypb)>0
local function Kpb(Lpb)
local Mpb=0
for Npb,Opb in ipairs(Lpb)do
if not N.isFarm(Opb.unit_id)and not N.allyBuff(Opb.unit_id)then
Mpb=Mpb+N.cap(Opb)
end
end
return Mpb
end
local Ppb
while#Bpb<6 do
local Qpb,Rpb
local Spb=Jpb and Epb(Bpb)==0
for Tpb,Upb in ipairs(ypb)do
local Vpb=false
for Wpb,Xpb in ipairs(Bpb)do
if Xpb.unit_id==Upb.unit_id then
Vpb=true
end
end
if not Vpb and(not Spb or N.isFarm(Upb.unit_id))then
local Ypb=table.clone(Bpb)
table.insert(Ypb,Upb)
local Zpb=W.run(wpb,W.teamFrom(Ypb,wpb.map),{hpMul=Cpb})
local _pb=W.objective(Zpb)
if not Rpb or _pb>Rpb then
Qpb,Rpb,Ppb=Upb,_pb,Zpb
end
end
end
if not Qpb then
break
end
table.insert(Bpb,Qpb)
end
if Jpb and Epb(Bpb)==0 then
local aqb,bqb
for cqb=1,#Bpb do
for dqb,eqb in ipairs(ypb)do
if N.isFarm(eqb.unit_id)then
local fqb=table.clone(Bpb)
fqb[cqb]=eqb
local gqb=W.run(wpb,W.teamFrom(fqb,wpb.map),{hpMul=Cpb})
local hqb=W.objective(gqb)
if not bqb or hqb>bqb then
aqb,bqb,Ppb=fqb,hqb,gqb
end
end
end
end
if aqb then
Bpb=aqb
end
end
local function iqb(jqb,kqb)
local lqb=W.teamFrom(jqb,wpb.map)
return(W.objective(kqb)+W.objective(W.run(wpb,lqb,{hpMul=Cpb*0.92}))+W.objective(W.run(wpb,lqb,{hpMul=Cpb*1.08})))/3
end
local mqb,nqb=Ppb or Dpb,iqb(Bpb,Ppb or Dpb)
if type(ypb.rest)==Atc[1440]and#ypb.rest>0 then
local oqb,pqb
for qqb,rqb in ipairs(Bpb)do
if not N.isFarm(rqb.unit_id)and not N.allyBuff(rqb.unit_id)then
local sqb,tqb=pcall(N.score,rqb,wpb.mod)
tqb=(sqb and tqb or 0)*N.skinMul(rqb,wpb.skinSet)
if not pqb or tqb<pqb then
oqb,pqb=qqb,tqb
end
end
end
if oqb then
local uqb,vqb={},M.now()
for wqb,xqb in ipairs(ypb.rest)do
if M.now()-vqb>5 then
break
end
local yqb=false
for zqb,Aqb in ipairs(Bpb)do
if Aqb.unit_id==xqb.unit_id then
yqb=true
end
end
if not yqb then
local Bqb=table.clone(Bpb)
Bqb[oqb]=xqb
table.insert(uqb,{u=xqb,o=W.objective(W.run(wpb,W.teamFrom(Bqb,wpb.map),{hpMul=Cpb}))})
end
end
table.sort(uqb,function(Cqb,Dqb)
return Cqb.o>Dqb.o
end)
ypb=table.clone(ypb)
for Eqb=1,math.min(4,#uqb)do
table.insert(ypb,1,uqb[Eqb].u)
end
Apb=Apb+(M.now()-vqb)
end
end
for Fqb=1,2 do
local Gqb=false
for Hqb=1,#Bpb do
for Iqb,Jqb in ipairs(ypb)do
if M.now()-Apb>zpb then
return Bpb,mqb,Cpb,Dpb
end
local Kqb=false
for Lqb,Mqb in ipairs(Bpb)do
if Mqb.unit_id==Jqb.unit_id then
Kqb=true
end
end
if not Kqb then
local Nqb=table.clone(Bpb)
Nqb[Hqb]=Jqb
if(not Jpb or Epb(Nqb)>0)and Kpb(Nqb)>=math.min(8,Kpb(Bpb))then
local Oqb=W.run(wpb,W.teamFrom(Nqb,wpb.map),{hpMul=Cpb})
local Pqb=W.objective(Oqb)
if Pqb>nqb+1 then
Pqb=iqb(Nqb,Oqb)
if Pqb>nqb+1 then
Bpb,nqb,mqb,Gqb=Nqb,Pqb,Oqb,true
end
end
end
end
end
end
if not Gqb then
break
end
end
return Bpb,mqb,Cpb,Dpb
end
function W.evolutions()
local Qqb=H.session()
local Rqb,Sqb={},{}
local Tqb=Qqb.inventory
local function Uqb(Vqb)
local Wqb=0
pcall(function()
Wqb=Tqb:get_number_of_owned_item(Vqb)
end)
return Wqb
end
for Xqb,Yqb in pairs(Qqb.profile_data.collection.owned_units)do
local Zqb=H.Units[Yqb.unit_id]
if Zqb and Zqb.evolve and Zqb.evolve.evolve_unit and not Zqb.evolve.hide_from_ui and not Sqb[Yqb.unit_id]and H.Units[Zqb.evolve.evolve_unit]then
Sqb[Yqb.unit_id]=true
local _qb=Yqb.shiny and Zqb.evolve.shiny or Zqb.evolve.normal
if _qb then
local arb={}
for brb,crb in pairs(_qb.item_requirement or{})do
if Uqb(crb.item_id)<(crb.amount or 1)then
table.insert(arb,string.format(Atc[2012],(H.Items[crb.item_id]or{}).name or crb.item_id,Uqb(crb.item_id),crb.amount))
end
end
for drb,erb in pairs(_qb.unit_requirement or{})do
local frb=0
for grb,hrb in pairs(Qqb.profile_data.collection.owned_units)do
if hrb.unit_id==erb.unit_id and(not erb.shiny or hrb.shiny)then
frb=frb+1
end
end
if frb<(erb.amount or 1)then
table.insert(arb,string.format(Atc[2012],N.name(erb.unit_id),frb,erb.amount))
end
end
local irb=ab.killsShort(Qqb.collection:get_unit_by_uuid(Yqb.uuid)or Yqb,_qb)
if irb then
table.insert(arb,string.format(Atc[2289],irb.what,M.fmt(irb.have),M.fmt(irb.need)))
end
if#arb<=1 then
local jrb=Qqb.collection:get_unit_by_uuid(Yqb.uuid)or Yqb
table.insert(Rqb,{u=jrb,from=Yqb.unit_id,to=Zqb.evolve.evolve_unit,missing=arb,evolved={unit_id=Zqb.evolve.evolve_unit,uuid=Atc[2004]..tostring(jrb.uuid),xp=jrb.xp,traits=jrb.traits,trait_stats=jrb.trait_stats,further_modifiers=jrb.further_modifiers}})
end
end
end
end
return Rqb
end
function W.levelFor(krb)
local lrb=J.simCal[krb.key]
if krb.kind==Atc[1592]and J.live.daily and J.live.daily.ld then
return J.live.daily.ld,J.live.daily.challenge
end
if eb.is(krb.level)and J.live.event and J.live.event.ld then
return J.live.event.ld,nil
end
local mrb=krb.kind~=Atc[1454]or(lrb and type(lrb.ld)==Atc[1440]and lrb.ld.id==krb.level and lrb.ch==krb.challenge)
if lrb and type(lrb.ld)==Atc[1440]and mrb then
return lrb.ld,lrb.ch
end
if krb.kind==Atc[1454]and H.Levels[krb.level]then
local nrb=W.slim(H.Levels[krb.level])
nrb._difficulty=Atc[1629]
nrb._gamemode=Atc[1454]
nrb._challenge=krb.challenge
return nrb,krb.challenge
end
if H.Levels[krb.level]then
local orb=W.slim(H.Levels[krb.level])
orb._difficulty=krb.diff
orb._gamemode=orb._OVERRIDE_GAMEMODE or((krb.kind==Atc[1476]or krb.kind==Atc[1593])and Atc[1476])or(orb.infinite and Atc[1459])or Atc[1475]
return orb,nil
end
end
function W.plan(prb,qrb,rrb,srb)
local trb,urb=W.levelFor(prb)
if prb.ldOverride then
trb=prb.ldOverride
end
if not trb then
return nil
end
local vrb=prb.mod or(prb.kind==Atc[1592]and J.live.daily and J.live.daily.mod)or O.levelMod(prb.level)
local wrb=W.info(trb,prb.key,urb,vrb)
local xrb=srb
if not xrb then
xrb={}
for yrb,zrb in ipairs(N.equipped())do
table.insert(xrb,zrb.u)
end
end
local Arb=W.teamFrom(xrb,wrb.map)
local Brb=W.evaluate(wrb,Arb)
local Crb,Drb=pcall(W.zoneChoice,wrb,Arb,Brb.p>=0.92 and 1.7 or Brb.p>=0.7 and 1.3 or 1,false)
if Crb and Drb then
wrb.zone=true
Brb=W.evaluate(wrb,Arb)
Brb.zone=true
Brb.margin=Brb.margin..Atc[2654]
end
Brb.sig=W.sig(xrb)
Brb.trust=W.trust(wrb,Arb)
Brb.label=prb.label
Brb.calibrated=(tonumber(wrb.cal.n)or 0)>0
J.simRes[prb.key]=Brb
Brb.aliveAt=nil
j.log(1,Atc[2655],string.format(Atc[2656],prb.label,Brb.margin,Brb.calibrated and Atc[2657]or Atc[2658],Brb.trust and string.format(Atc[2659],Brb.trust.ratio)or Atc[2660]))
local Erb=O.rec(prb.key)
if I.simTeams and qrb and type(Erb.winTeam)==Atc[1440]and#Erb.winTeam>0 then
local Frb=H.session()
local Grb={}
for Hrb,Irb in ipairs(Erb.winTeam)do
local Jrb=Frb.collection:get_unit_by_uuid(Irb)
if Jrb then
table.insert(Grb,Jrb)
end
end
if#Grb== #Erb.winTeam then
local Krb=W.teamFrom(Grb,wrb.map)
local Lrb=W.run(wrb,Krb,{hpMul=1})
local Mrb=W.trust(wrb,Krb)
local Nrb=Mrb and not Mrb.ok
if not Lrb.won or Nrb then
local Orb,Prb={},{}
for Qrb,Rrb in ipairs(Grb)do
table.insert(Orb,N.name(Rrb.unit_id))
table.insert(Prb,Rrb.unit_id)
end
J.simTeam[prb.key]={uuids=Erb.winTeam,names=Orb,ids=Prb,won=true,wave=wrb.total,better=W.sig(Grb)~=Brb.sig,cur={won=Brb.won,wave=Brb.wave},at=os.time(),label=prb.label,base=Brb.sig,why=Atc[2661]}
j.log(1,Atc[2655],string.format(Atc[2662],prb.label,table.concat(Orb,Atc[1536]),Nrb and string.format((Mrb.ratio or 0)<0.1 and Atc[2663]or Atc[2664],Mrb.ratio or 0)or string.format(Atc[2665],Lrb.wave),Erb.winTeamN or 1))
return Brb
end
end
end
if I.simTeams and qrb then
local Srb,Trb,Urb,Vrb,Wrb=pcall(W.bestTeam,wrb,xrb,W.pool(vrb,wrb),rrb)
if Srb and Trb then
local Xrb=W.sig(Trb)~=Brb.sig
if Xrb and Brb.won and(Brb.p or 0)>=0.92 then
local Yrb={}
for Zrb,_rb in ipairs(Trb)do
table.insert(Yrb,N.name(_rb.unit_id))
end
j.log(1,Atc[2655],string.format(Atc[2666],prb.label,table.concat(Yrb,Atc[1536])))
