if not qxb.bought and not cb.isCurse(qxb.id)then
qxb.luck=tonumber(cb.item(qxb.id).luck_increase)~=nil
qxb.v=cb.itemValue(qxb.id,gxb)
if not qxb.luck and qxb.v/math.max(1,qxb.cost)<cb.MIN_WORTH then
oxb=oxb+1
