table.insert(mxb,qxb)
end
end
end
table.sort(mxb,function(rxb,sxb)
if rxb.luck~=sxb.luck then
return rxb.luck
end
return rxb.v/math.max(1,rxb.cost)>sxb.v/math.max(1,sxb.cost)
end)
local txb,uxb,vxb={},0,0
for wxb,xxb in ipairs(mxb)do
if xxb.cost<=jxb-(xxb.luck and 0 or lxb)then
if cb.buy(xxb)then
jxb=cb.res(cb.data())
table.insert(txb,string.format(Atc[2748],tostring(cb.item(xxb.id).name or xxb.id),xxb.cost))
end
elseif xxb.cost<=jxb then
vxb=vxb+1
else
uxb=uxb+1
end
end
cb.note(string.format(Atc[2749],ixb,#nxb>0 and table.concat(nxb,Atc[1536])or Atc[2750],#txb>0 and(Atc[2751]..table.concat(txb,Atc[1536]))or(ixb<10 and Atc[2752]or(vxb>0 and Atc[2753]or Atc[2754])),jxb,uxb>0 and string.format(Atc[2755],uxb)or Atc[369],vxb>0 and string.format(Atc[2756],vxb,lxb)or Atc[369],oxb>0 and string.format(Atc[2757],oxb)or Atc[369]))
