if nyb+oyb<=0 or iyb>=2 then
break
end
local pyb,qyb
if nyb>0 then
pyb,qyb=j.request(Atc[2773],Atc[2774])
else
pyb,qyb=j.request(Atc[2773],Atc[2774],true)
end
