end
cb.note(string.format(Atc[2777],gyb,hyb,ayb and Atc[2778]or(eyb<=1 and Atc[2779]or Atc[2780]),cb.luck(_xb),(tonumber(H.cur(Atc[1500]))or 0)-jyb))
local Dyb,Eyb,Fyb=cb.res(cb.data())
if(ayb or fyb>=cb.ROOMS)and Eyb+Fyb>0 then
cb.note(string.format(Atc[2781],Eyb,Fyb))
O.rec(Atc[1761]).restUntil=os.time()+1800
return Atc[2782]
end
if not ayb then
j.request(Atc[2758],Atc[2759])
end
end
