table.insert(nEb,{p=M.flat(pEb:GetPivot().Position),r=qEb.range.Value*(N.SUMMONER[qEb.id.Value]and N.SUMMONER[qEb.id.Value].reach or 1),air=Q.canAir(pEb)})
