local DEb=M.flat(CEb.pos)
for EEb,FEb in ipairs(nEb)do
if(DEb-FEb.p).Magnitude<=FEb.r then
local GEb=tostring(CEb.lane)
AEb[GEb]=(AEb[GEb]or 0)+1
if CEb.prog>(yEb[GEb]or 0)then
yEb[GEb]=CEb.prog
end
break
end
end
end
local HEb,IEb={},0
